    public void beforeLeave(BeforeLeaveEvent event) {
        if (!hasContent()) {
            return;
        }
        pendingLeave = event.postpone();
        if (leaveConfirmation == null) {
            leaveConfirmation = createLeaveConfirmation();
        }
        leaveConfirmation.open();
    }

    private Dialog createLeaveConfirmation() {
        Dialog dialog = new Dialog();
        dialog.setHeaderTitle("Discard this message?");
        dialog.setCloseOnEsc(false);
        dialog.setCloseOnOutsideClick(false);
        dialog.add(new Paragraph("The message has not been sent yet."));

        Button keepEditing = new Button("Keep editing", event -> {
            dialog.close();
            // Tells the client-side router that the navigation was called off,
            // so that following the same link again works.
            takePendingLeave().ifPresent(BeforeLeaveEvent.ContinueNavigationAction::cancel);
        });
        Button discard = new Button("Discard", event -> {
            dialog.close();
            takePendingLeave().ifPresent(BeforeLeaveEvent.ContinueNavigationAction::proceed);
        });
        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
        dialog.add(new HorizontalLayout(keepEditing, discard));
        return dialog;
    }

    private Optional<BeforeLeaveEvent.ContinueNavigationAction> takePendingLeave() {
        var action = pendingLeave;
        pendingLeave = null;
        return Optional.ofNullable(action);
    }
