+        FormLayout form = new FormLayout(name, email, phone, message);
+        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 1),
+                new FormLayout.ResponsiveStep("30em", 2));
+        form.setColspan(message, 2);
+
+        sentMessages.addColumn(ContactMessage::name).setHeader("Name");
+        sentMessages.addColumn(ContactMessage::message).setHeader("Message");
+        sentMessages.addColumn(ContactMessage::email).setHeader("Email");
+        sentMessages.addColumn(ContactMessage::phone).setHeader("Phone");
+        sentMessages.setAllRowsVisible(true);
+        refreshSentMessages();
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form,
+                new HorizontalLayout(send), sentMessages);
+    }
+
+    private void fieldEdited() {
+        if (!clearingFields) {
+            send.setEnabled(true);
+        }
+    }
+
+    private void trySend() {
+        clearErrors();
+
+        String nameValue = name.getValue().trim();
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        String messageValue = message.getValue();
+
+        boolean valid = true;
+        if (nameValue.isBlank()) {
+            markInvalid(name, "Name is required");
+            valid = false;
+        }
+        if (!emailValue.isEmpty() && !EMAIL_PATTERN.matcher(emailValue).matches()) {
+            markInvalid(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            markInvalid(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+        if (messageValue.isBlank()) {
+            markInvalid(message, "Message is required");
+            valid = false;
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            markInvalid(message, "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            valid = false;
+        }
+        if (!valid) {
+            return;
+        }
+
+        MessageStore.current().add(
+                new ContactMessage(nameValue, emailValue, phoneValue, messageValue.trim()));
+        refreshSentMessages();
+
+        Notification.show("Message sent")
+                .addThemeVariants(NotificationVariant.LUMO_SUCCESS);
+
+        clearFields();
+        // Enabled again as soon as the user edits any field.
+        send.setEnabled(false);
+    }
+
+    private void markInvalid(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void clearErrors() {
+        for (HasValidation field : new HasValidation[] { name, email, phone, message }) {
+            field.setInvalid(false);
+            field.setErrorMessage(null);
+        }
+    }
+
+    private void clearFields() {
+        clearingFields = true;
+        try {
+            name.clear();
+            email.clear();
+            phone.clear();
+            message.clear();
+        } finally {
+            clearingFields = false;
+        }
+    }
+
+    private void refreshSentMessages() {
+        sentMessages.setItems(MessageStore.current().all());
+    }
+
+    private boolean hasContent() {
+        return !name.getValue().isEmpty() || !email.getValue().isEmpty()
+                || !phone.getValue().isEmpty() || !message.getValue().isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasContent()) {
+            return;
+        }
+        pendingLeave = event.postpone();
+        if (leaveConfirmation == null) {
+            leaveConfirmation = createLeaveConfirmation();
+        }
+        leaveConfirmation.open();
+    }
+
+    private Dialog createLeaveConfirmation() {
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard this message?");
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        dialog.add(new Paragraph("The message has not been sent yet."));
+
+        Button keepEditing = new Button("Keep editing", event -> {
+            dialog.close();
+            // Tells the client-side router that the navigation was called off,
+            // so that following the same link again works.
+            takePendingLeave().ifPresent(BeforeLeaveEvent.ContinueNavigationAction::cancel);
+        });
+        Button discard = new Button("Discard", event -> {
+            dialog.close();
+            takePendingLeave().ifPresent(BeforeLeaveEvent.ContinueNavigationAction::proceed);
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        dialog.add(new HorizontalLayout(keepEditing, discard));
+        return dialog;
+    }
+
+    private Optional<BeforeLeaveEvent.ContinueNavigationAction> takePendingLeave() {
+        var action = pendingLeave;
+        pendingLeave = null;
+        return Optional.ofNullable(action);
+    }
+}
