+package com.example.contact;
+
+import java.io.Serializable;
+import java.util.ArrayList;
+import java.util.List;
+
+import com.vaadin.flow.server.VaadinSession;
+
+/**
+ * Keeps the messages that have been sent, newest first.
+ * <p>
+ * The store lives in the {@link VaadinSession}, so the list outlives a single
+ * visit to the contact view: navigating away and back shows the same messages.
+ */
+public class MessageStore implements Serializable {
+
+    /** Used only if there is no session at hand, which should not happen. */
+    private static final MessageStore NO_SESSION_FALLBACK = new MessageStore();
+
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    public static MessageStore current() {
+        VaadinSession session = VaadinSession.getCurrent();
+        if (session == null) {
+            return NO_SESSION_FALLBACK;
+        }
+        MessageStore store = session.getAttribute(MessageStore.class);
+        if (store == null) {
+            store = new MessageStore();
+            session.setAttribute(MessageStore.class, store);
+        }
+        return store;
+    }
+
+    public synchronized void add(ContactMessage message) {
+        messages.add(0, message);
+    }
+
+    /** All messages, newest first. */
+    public synchronized List<ContactMessage> all() {
+        return List.copyOf(messages);
+    }
+}
