+
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("about", test($(RouterLink.class).withText("About").single()).getPath());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
