+
+    @Test
+    void twoMessages_areListedNewestFirst() {
+        navigate(ContactView.class);
+        test(name()).setValue("Alice");
+        test(phone()).setValue("123");
+        test(message()).setValue("First");
+        test(send()).click();
+
+        test(name()).setValue("Bob");
+        test(phone()).setValue("456");
+        test(message()).setValue("Second");
+        test(send()).click();
+
+        var grid = test(grid(), ContactMessage.class);
+        assertEquals(2, grid.size());
+        assertEquals("Second", grid.getRow(0).message());
+        assertEquals("First", grid.getRow(1).message());
+    }
+
+    @Test
+    void sentMessages_surviveLeavingAndComingBack() {
+        navigate(ContactView.class);
+        fillValidForm();
+        test(send()).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        var grid = test(grid(), ContactMessage.class);
+        assertEquals(1, grid.size());
+        assertEquals("Alice", grid.getRow(0).name());
